const noIntervention=[p('The selected studies are not trials showing that a shielding product, sticker, fabric or change in device use improves this outcome. A laboratory attenuation result would answer an engineering question; demonstrating a health benefit requires an appropriate health-outcome comparison. Do not treat the presence of an association as proof that reversing an exposure improves health.'),p('Evaluate the exact claim being made: reduction in a measured field, reduction in actual user exposure, or a change in a clinical outcome. These claims need different evidence. No product-specific health recommendation follows from the selected records on this page.')];
const baseOutcomes:Topic[]=[
 {id:'brain-tumours',kind:'outcome',title:'EMF and brain tumours',intro:'Compare the selected human phone studies without merging different tumour types, exposure histories or study designs.',aliases:['brain cancer','glioma','meningioma','acoustic neuroma','vestibular schwannoma'],guide:'wireless',takeaway:'Included cohorts did not show increased brain-tumour risk under studied conditions; the highest recalled-use group in INTERPHONE differed. These selected reports do not establish one verdict for every EMF exposure.',overview:[p('“Brain tumours” is an umbrella outcome. Glioma, meningioma and acoustic neuroma are distinct diagnoses, and their results need to stay identifiable. The direct human evidence presented here concerns mobile-phone use. It does not supply matched results for Wi-Fi, static fields or every other exposure category.',['cosmos','million-women']),p('A prospective cohort records exposure before later diagnoses; a case-control study starts from disease status and reconstructs earlier exposure. Their different vulnerabilities matter when the findings differ. Reading the designs and exposure methods is more informative than counting favorable and unfavorable papers.',['cosmos','interphone'])],modules:outcomeModules(
 [p('The selected cohorts examine diagnosed tumours rather than a general symptom or laboratory biomarker. COSMOS distinguishes glioma, meningioma and acoustic neuroma. A result for a broad tumour group is not automatically a result for each subtype or for a different age group.',['cosmos','million-women']),p('For young people, MOBI-Kids addresses neuroepithelial tumours in its own age range. Its result should remain on the child-and-adolescent comparison rather than being silently generalized to a lifetime beginning in infancy.',['mobi-kids'])],
 [p('INTERPHONE’s highest recalled call-time group showed elevated glioma odds, while recall and participation bias limit a causal interpretation. Cohorts reduce the reliance on recalling exposure after diagnosis, but they still have exposure error, limited rare-tumour counts and latency questions. Neither design removes every source of uncertainty.',['interphone','cosmos']),p('The Million Women Study has a particular age and sex distribution and relatively coarse use categories. Its findings do not directly describe children, precise absorbed doses or every heavy-use scenario.',['million-women'])],
 [p('A short sham-exposure experiment can test an acute response. It does not replicate years of exposure followed by cancer diagnoses. The human cancer comparisons presented here are observational; the animal bioassays answer a separate hazard question with species and dose limits.',['ntp-rats','ramazzini'])],noIntervention),faqs:[{q:'Do the phone cohorts prove that no risk is possible?',a:'No. Their results have defined populations, exposure estimates, tumour counts and follow-up. Rare subtypes, longer latency and exposure error remain limitations.'},{q:'Why are animal findings shown separately?',a:'They can inform hazard questions, but experimental dose, species and exposure schedules differ from human phone use. They do not supply a direct numerical human-risk estimate.'}]},
 {id:'childhood-brain-tumours',kind:'outcome',title:'EMF and childhood brain tumours',intro:'What MOBI-Kids can tell us about wireless-phone use in young people, and what remains outside its scope.',aliases:['children cancer','child brain','teen brain'],guide:'children',takeaway:'MOBI-Kids found no evidence of a causal association in the population studied. Bias and exposure error limit what can be ruled out.',overview:[p('Children’s questions need evidence from the relevant age range and outcome, rather than a result copied from adult cohorts. MOBI-Kids studied wireless-phone use and neuroepithelial brain tumours in young people. It is a specific case-control comparison, not a lifetime study beginning at birth.',['mobi-kids']),p('The authors found no evidence of a causal association. The source record also preserves an important limitation: potential bias and exposure error mean a small increased risk cannot be ruled out. Both parts belong in the answer.',['mobi-kids'])],modules:outcomeModules([p('The outcome is neuroepithelial brain tumours, not all childhood cancers or every aspect of development. The participant age range extends into young adulthood. Those boundaries matter when a claim is made about infants or lifetime exposure.',['mobi-kids'])],[p('A case-control study must reconstruct earlier exposure and recruit a suitable comparison group. Potential bias and exposure error limit how strongly a negative finding can exclude a small risk. Adult cohort results do not remove those limitations for children.',['mobi-kids','million-women'])],[p('An acute blinded exposure test cannot reproduce a childhood cancer follow-up. This page’s selected direct human record is observational; no sham trial of tumour development is presented.',['mobi-kids'])],noIntervention),faqs:[{q:'Does this study follow children from infancy for life?',a:'No. MOBI-Kids studied participants aged 10–24 in a case-control design. It is not lifetime follow-up from infancy.'},{q:'Can adult evidence answer every child-specific question?',a:'No. Population, exposure history, follow-up and outcome must match. Adult results can be context while child-specific questions remain separate.'}]},
 {id:'childhood-leukaemia',kind:'outcome',title:'Magnetic fields and childhood leukaemia',intro:'Higher residential magnetic-field categories show an association in selected observational analyses; causation and exposure measurement remain central questions.',aliases:['leukemia','leukaemia','childhood leukemia','elf cancer'],guide:'power-lines',takeaway:'The association in higher exposure categories is an observation that requires explanation. It is not proof of causation, a personal-risk estimate or an exact safe threshold.',overview:[p('The direct human evidence presented here concerns residential power-frequency magnetic fields and childhood leukaemia. It includes pooled analyses of source studies and a separate study using birth-address distance from high-voltage lines. These are different ways of defining exposure.',['ahlbom','greenland','draper']),p('The pooled analyses reported elevated estimates in the relatively uncommon higher-field categories. They overlap in underlying studies, so their report count cannot be used as an independent-study count. Keep the observation, its uncertainty and the exposure proxy together.',['ahlbom','greenland'])],modules:outcomeModules([p('The health outcome is childhood leukaemia. The exposure measures include estimated or measured residential magnetic fields, wiring proxies and distance. None is interchangeable with a spot reading from a household device or an RF measurement near a router.',['ahlbom','greenland','draper'])],[p('Selection bias and other explanations remain possible in the pooled observational evidence. In the distance study, the association extended farther than expected for line-related fields. That makes it especially important not to translate distance categories into a causal dose–response rule.',['ahlbom','draper'])],[p('An acute sham experiment cannot establish whether a long-term exposure causes childhood leukaemia. These selected records are observational and pooled analyses, rather than randomized trials of disease development. Controlled evidence for a different short-term endpoint would not answer the same question.',['ahlbom','greenland'])],noIntervention),faqs:[{q:'Why can’t I count the two pooled analyses as two new cohorts?',a:'They combine underlying source studies, with overlap between the analyses. Independent families need to be reconciled before counting the evidence.'},{q:'Does a category boundary mark where disease begins?',a:'No. A boundary used to analyze exposure is not an experimentally demonstrated disease threshold or a regulatory limit.'}]},
 {id:'sleep',kind:'outcome',title:'EMF and sleep',intro:'Sleep quality, sleep stages and EEG features are different outcomes. Start with what was measured and which signal was tested.',aliases:['insomnia','melatonin','sleep stages','EEG','router at night'],guide:'sleep',takeaway:'The included 5G experiment found a genotype-specific sleep-spindle change. It does not establish clinical sleep harm, and a direct Wi-Fi sleep verdict is not presented in this edition.',overview:[p('Sleep evidence is easy to overstate when a physiological measurement is substituted for a clinical outcome. The public experiment linked here measured the sleep electroencephalogram after specified 5G exposures. Its reported change concerns spindle center frequency in one genotype group, rather than a demonstrated population-wide effect on insomnia.',['5g-sleep']),p('The Wi-Fi question remains separate. Sharing the RF category does not make a 5G signal experiment a router experiment. Likewise, a study of phone habits may mix radiofrequency exposure with other aspects of device use. A useful answer identifies the signal, timing, population and sleep endpoint before interpreting the finding.',['5g-sleep'])],modules:outcomeModules([p('Distinguish subjective sleep quality, duration, sleep stages, EEG features and a clinical sleep complaint. They can be investigated separately and do not become the same outcome because all are associated with sleep. The included experiment’s genotype-specific EEG finding should retain that precise description.',['5g-sleep'])],[p('Changing a device setting can change more than exposure. Bedtime routines and use of the device may change too. Such alternatives need an appropriate study comparison; they should not be asserted as the cause of a result without evidence. A change after turning something off does not, by itself, identify RF as the explanation.')],[p('The included 5G study used a double-blind, sham-controlled protocol before sleep. That design addresses the specified acute comparison. Its small, genotyped sample and EEG endpoint limit transfer to all users, all signals, long-term exposure or clinical insomnia.',['5g-sleep'])],noIntervention),faqs:[{q:'Is a sleep-spindle change the same as insomnia?',a:'No. A physiological EEG feature and a clinical sleep disorder are different endpoints. The included finding does not by itself establish clinical harm.'},{q:'Does this page establish a benefit from turning Wi-Fi off?',a:'No. The direct public experiment uses specified 5G signals. No direct Wi-Fi/sleep result or router-off health benefit is established by this selected-source edition.'}]},
 {id:'male-fertility',kind:'outcome',title:'EMF and male fertility',intro:'Keep semen measures, pregnancy outcomes and isolated-cell experiments in separate evidence streams.',aliases:['sperm','semen','fertility','conception','phone pocket'],guide:'fertility',takeaway:'Selected human studies report mixed associations. They do not establish that ordinary phone carrying causes infertility; laboratory sperm findings answer a different question.',overview:[p('“Fertility” can refer to a semen measurement, the chance of conception over time or a laboratory response in sperm outside the body. Those endpoints are not interchangeable. The human records here study self-reported phone behavior and carrying, rather than a directly measured RF dose.',['rahban','hatch']),p('The cross-sectional Swiss study found an association with lower total sperm count, with differences across semen measures. The preconception cohorts found little overall association between front-pocket carrying and fecundability, with a subgroup finding. Neither result should be reduced to a general causal claim.',['rahban','hatch'])],modules:outcomeModules([p('Sperm concentration, total count, motility and vitality describe different semen properties. Fecundability concerns conception over time. The isolated-sperm experiment measures cellular responses under laboratory exposure, rather than pregnancy outcomes in men.',['rahban','hatch','de-iuliis','de-iuliis-correction'])],[p('Self-reported use and phone location are imprecise exposure proxies. Cross-sectional comparisons do not establish temporal order or isolate RF from lifestyle and other differences. Prospective pregnancy follow-up addresses a different endpoint, but residual confounding and subgroup interpretation still matter.',['rahban','hatch'])],[p('The controlled cellular experiment exposed purified sperm outside the body. Its results are relevant to that model; they do not reproduce intact-body physiology or establish the effect of ordinary phone carrying. Preserve the correction to Figure 1D and replicate reporting when reading it.',['de-iuliis','de-iuliis-correction'])],noIntervention),faqs:[{q:'Does a semen association establish infertility?',a:'No. Semen measures and conception are different outcomes, and an observational association does not establish cause.'},{q:'Why is one pregnancy estimate not displayed?',a:'The indexed abstract contains a malformed confidence interval. The numerical estimate remains withheld pending a full-text check; it has not been reconstructed.'}]},
 {id:'ehs-symptoms',kind:'outcome',title:'Electromagnetic hypersensitivity and symptoms',intro:'Symptoms, attribution to exposure and the results of a blinded provocation test are distinct questions.',aliases:['electrosensitivity','sensitivity','EHS','symptoms','nocebo'],guide:'symptoms',takeaway:'The included blinded experiment did not attribute symptoms to the tested signals. This finding does not dismiss the symptoms or establish their cause.',overview:[p('A symptom report describes a person’s experience. Testing whether a particular signal triggers that symptom requires a separate comparison. In the selected base-station provocation experiment, blinded exposure did not increase symptom number or severity attributable to the tested signals.',['eltiti']),p('Open-label and blinded findings differed. That observation makes blinding important, but it does not by itself prove a single explanation for every participant’s symptoms. Short experiments also cannot address every chronic or delayed outcome.',['eltiti'])],modules:outcomeModules([p('The experiment considers symptom number and severity in people reporting sensitivity and controls. Those measures are different from a tumour diagnosis, an EEG feature or a general judgment about a person’s health. Read the exposure window and actual outcome together.',['eltiti'])],[p('If participants know the exposure condition, awareness can affect reporting and interpretation. Blinded testing helps separate that knowledge from the signal comparison. Withdrawal and the unresolved control-count discrepancy remain limitations of this source; neither should disappear when summarizing its result.',['eltiti'])],[p('GSM/UMTS-like signals were compared with sham in a double-blind provocation design. The reported null symptom comparison applies to the tested acute conditions. It is not proof that symptoms are imaginary, nor does it identify the cause of symptoms outside that setting.',['eltiti'])],noIntervention),faqs:[{q:'Does a negative provocation result mean symptoms are imaginary?',a:'No. Symptom occurrence and attribution to the tested signal are separate. A blinded experiment can question a proposed trigger without dismissing the experience.'},{q:'Does a sham comparison prove a nocebo mechanism?',a:'No. That would need its own evidence and design. A difference between open-label and blinded observations alone does not identify the cause of each person’s symptoms.'}]},
 {id:'headache',kind:'outcome',title:'EMF and headaches',intro:'A small sham-controlled experiment tests short-term symptom triggering, with clear limits on generalization.',aliases:['headaches','pain','migraine'],guide:'symptoms',takeaway:'Pain and discomfort did not differ significantly between RF and sham in the included selected sample. This is not an assessment of every cause of headache.',overview:[p('The direct record on this page is a blinded provocation experiment in people who reported mobile-phone headaches. It compares pain and discomfort during RF and sham exposures. That is a focused question about short-term triggering, rather than a study of every headache disorder.',['headache']),p('The experiment did not find a significant difference between the conditions. A small, selected sample and an acute exposure window constrain how widely this result can be applied. It should neither be inflated into universal reassurance nor taken as an explanation for an individual’s symptoms.',['headache'])],modules:outcomeModules([p('The measured outcomes were pain and discomfort, rather than a new cancer diagnosis or a general measure of neurological injury. The symptom-reporting participant group is consequential: the experiment was not a representative long-term population study.',['headache'])],[p('A symptom occurring during device use does not by itself identify which aspect of the setting caused it. The blinded comparison is designed to test the specified RF condition; it does not diagnose alternative causes or prove why a particular participant experienced pain.',['headache'])],[p('The experiment used double-blind sham control. Its result concerns the real-versus-sham comparison under those conditions, with the sample-size and short-term limitations retained. Other exposures and delayed endpoints need their own direct evidence.',['headache'])],noIntervention),faqs:[{q:'Does a nonsignificant comparison prove an effect is impossible?',a:'No. Sample size, uncertainty, exposure conditions and the endpoint determine what the experiment can resolve.'},{q:'Does this study explain every phone-associated headache?',a:'No. It tests a specified RF-versus-sham comparison in selected participants, rather than diagnosing every headache or testing every aspect of device use.'}]},
 {id:'cognition',kind:'outcome',title:'EMF, attention and memory',intro:'Read modeled brain dose and memory change without turning a specific observational result into a general developmental claim.',aliases:['attention','memory','cognitive','brain fog','HERMES'],guide:'symptoms',takeaway:'HERMES reported a figural-memory association, with a full-sample interval that included no difference. Modeled exposure and subgroup results limit causal interpretation.',overview:[p('The selected human record is HERMES, a prospective adolescent cohort relating modeled RF brain dose to one-year memory change. It addresses a particular memory outcome, population and interval. It is not a single test of every cognitive function or lifelong development.',['hermes']),p('The full-sample estimate and the operator-data subset have different uncertainty intervals. Keeping them distinct matters: emphasizing a selected analysis while omitting the full sample can make the evidence appear more decisive than it is. The source record preserves both and its causal limitations.',['hermes'])],modules:outcomeModules([p('Memory performance in a particular test is an outcome with its own scale and follow-up. Figural-memory change is not synonymous with attention, intelligence, clinical brain injury or all cognitive development. A broader claim would require evidence about those actual endpoints.',['hermes'])],[p('Modeled exposure is an estimate, not direct measurement of every participant’s brain dose. Residual confounding and subgroup analyses limit the causal interpretation. A prospective design establishes the study sequence but does not remove these sources of uncertainty.',['hermes'])],[p('HERMES is an observational cohort rather than a randomized sham-exposure trial. A controlled acute experiment would answer a different question and would need a defined signal, comparison and cognitive endpoint. No such matched synthesis is supplied by this selected record.',['hermes'])],noIntervention),faqs:[{q:'Does HERMES prove RF impairs development?',a:'No. It concerns a particular memory change and modeled exposure in adolescents, with residual confounding and uncertainty. It does not establish a general developmental effect.'},{q:'Why show the full sample as well as a subset?',a:'Selected analyses can differ from the full sample. Reading both preserves uncertainty and avoids treating one subgroup result as the whole study.'}]},
 {id:'animal-cancer',kind:'outcome',title:'EMF and cancer in animals',intro:'Long-term rat bioassays contribute to hazard assessment, with exposure, species and tumour-specific limits.',aliases:['NTP','Ramazzini','rat cancer','schwannoma'],guide:'animal-studies',takeaway:'The included experiments reported animal tumour signals under their exposure conditions. They do not provide a numerical cancer-risk estimate for a person using a phone.',overview:[p('Animal bioassays can control exposure over a large part of the lifespan in ways human observational studies cannot. The two programs presented here are NTP and Ramazzini. Their findings belong in a clearly labeled animal-evidence stream, with sex, tumour and exposure conditions kept visible.',['ntp-rats','ramazzini']),p('NTP judged the evidence for malignant heart schwannomas in exposed male rats clear, with variation by sex and tumour. Ramazzini reported an increase in male-rat heart schwannomas at its highest tested exposure. These are bounded findings; translating them into human risk requires additional reasoning.',['ntp-rats','ramazzini'])],modules:outcomeModules([p('The outcomes are tumours in rats, not diagnoses in human phone users. Species, sex, survival and tumour type are part of the result. A finding for heart schwannomas should not be described simply as proof of every kind of brain cancer.',['ntp-rats','ramazzini'])],[p('Small tumour counts and survival differences can affect interpretation. Experimental control does not eliminate species and exposure differences when the question changes to people. Assess the study’s own comparison before making a human-health inference.',['ntp-rats','ramazzini'])],[p('These are controlled long-term animal exposures. Whole-body dose and schedule differ from human phone-use estimates, and the two experiments use different RF conditions. They are not acute human sham tests or equivalent versions of a human cohort.',['ntp-rats','ramazzini'])],noIntervention),faqs:[{q:'Should animal evidence be ignored?',a:'No. It is important hazard and mechanistic evidence. Its relevance to human exposure needs explicit reasoning about dose, species, schedule and endpoint.'},{q:'Can I scale the dose to calculate my own risk?',a:'No. These selected records do not establish a validated dose-to-risk model for that calculation.'}]},
 {id:'dna-damage',kind:'outcome',title:'EMF and DNA damage',intro:'A cellular endpoint needs its model and exposure conditions; it is not itself a diagnosis of disease.',aliases:['genotoxicity','oxidative stress','DNA fragmentation'],guide:'fertility',takeaway:'The selected isolated-sperm experiment reported DNA fragmentation and other cellular changes. It does not establish disease or infertility from everyday exposure.',overview:[p('DNA-damage claims need to identify the cells, assay, exposure and correction status. The selected record here concerns purified human sperm outside the body, rather than an intact-person experiment. Its reported cellular changes are therefore a model-specific finding.',['de-iuliis','de-iuliis-correction']),p('The study’s correction replaces Figure 1D and specifies biological replicates. Keeping that notice attached to the source matters more than repeating the title alone. A laboratory observation can inform a mechanism question without supplying a clinical diagnosis or a direct estimate of everyday risk.',['de-iuliis','de-iuliis-correction'])],modules:outcomeModules([p('DNA fragmentation, oxidative stress, motility and vitality are distinct cellular measurements. The sample consists of purified sperm outside the body. Neither the name “human sperm” nor the detection of an assay change makes this a trial of fertility outcomes in men.',['de-iuliis'])],[p('The isolated preparation and experimental exposure differ from intact-body physiology and ordinary phone carrying. Those differences are limits on translation, rather than variables that can be ignored because a result is statistically significant.',['de-iuliis'])],[p('The cellular exposure is controlled, but it is not a human randomized trial. The correction and distinction between biological and technical replication remain essential to reading the experiment. No human clinical grade is assigned from this source.',['de-iuliis','de-iuliis-correction'])],noIntervention),faqs:[{q:'Does an assay change establish cancer or infertility?',a:'No. A cellular measurement and a clinical disease outcome are different. Translation requires evidence beyond the assay result.'},{q:'Is the correction attached to the original study?',a:'Yes. The source links retain the correction to Figure 1D and biological-replicate reporting, so it can be read with the experiment.'}]}
];
type TopicAddition={takeaway?:string;overview?:Paragraph[];modules?:Record<string,Paragraph[]>;faqs?:{q:string;a:string}[]};
const additions=topicOverrides.additions as Record<string,TopicAddition>;
function expanded(t:Topic):Topic{const replacement=(topicOverrides.topics as Topic[]).find(x=>x.id===t.id&&x.kind===t.kind);if(replacement)return replacement;const a=additions[t.id];if(!a)return t;return {...t,takeaway:a.takeaway||t.takeaway,overview:a.overview||t.overview,faqs:a.faqs||t.faqs,modules:t.modules.map(m=>({...m,paragraphs:a.modules?.[m.id]?(t.id==='sleep'||t.id==='cognition'?a.modules[m.id]:[...m.paragraphs,...a.modules[m.id]]):m.paragraphs}))}}
export const sources:Topic[]=[...baseSources,...(newTopics as Topic[]).filter(t=>t.kind==='source')].map(expanded);
export const outcomes:Topic[]=[...baseOutcomes,...(newTopics as Topic[]).filter(t=>t.kind==='outcome')].map(expanded);
export const fields:Topic[]=newFields as Topic[];
export const evidenceRows:EvidenceRow[]=[...baseRows.filter(r=>r.id!=='wifi-sleep-gap'),...(newComparisons as EvidenceRow[])];
export const topicRegistry=registry;
export function topicHref(topic:Topic){return '/'+(topic.kind==='source'?'sources':topic.kind==='field'?'fields':'outcomes')+'/'+topic.id}
export function rowsFor(topic:Topic){return evidenceRows.filter(r=>topic.kind==='source'?r.source===topic.id:topic.kind==='field'?r.field===topic.id:r.outcome===topic.id)}
export function rowCitations(row:EvidenceRow){return [...row.papers,...(row.papers.includes('de-iuliis')?['de-iuliis-correction']:[])];}
export function citationsFor(topic:Topic){return [...new Set([...topic.overview.flatMap(p=>p.refs||[]),...rowsFor(topic).flatMap(rowCitations),...topic.modules.flatMap(m=>m.paragraphs.flatMap(p=>p.refs||[])),...(rowsFor(topic).some(r=>r.papers.includes('de-iuliis'))?['de-iuliis-correction']:[])])];}
